DECLARE
  v_button PLS_INTEGER;
BEGIN
  IF :BK_ORDER.STATUS != 'DRAFT' THEN
    om_shared.show_message('Only DRAFT orders can be submitted.');
    RETURN;
  END IF;

  v_button := SHOW_ALERT('AL_CONFIRM_SUBMIT');
  IF v_button != ALERT_BUTTON1 THEN
    RETURN;
  END IF;

  COMMIT_FORM;

  lom_order_api.submit_order(:BK_ORDER.ORDER_ID);
  COMMIT;
  om_shared.show_message('Order ' || :BK_ORDER.ORDER_ID || ' submitted.');
  EXECUTE_QUERY;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    om_shared.show_message('Submit failed: ' || SQLERRM);
END;

BEGIN
  CLEAR_FORM(NO_VALIDATE);
  GO_BLOCK('BK_ORDER');
  CREATE_RECORD;
END;

BEGIN
  :GLOBAL.G_USER := NVL(:GLOBAL.G_USER, GET_APPLICATION_PROPERTY(USERNAME));
  GO_BLOCK('BK_APPROVAL');
  EXECUTE_QUERY;
END;

BEGIN
  IF :BK_CUSTOMER.EMAIL IS NOT NULL
     AND NOT REGEXP_LIKE(:BK_CUSTOMER.EMAIL, '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') THEN
    om_shared.show_message('Email address does not look valid.');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;
END;

BEGIN
  IF :BK_INVENTORY.QUANTITY_AVAILABLE <= :BK_INVENTORY.REORDER_LEVEL THEN
    :BK_INVENTORY.LOW_STOCK_FLAG := 'YES';
  ELSE
    :BK_INVENTORY.LOW_STOCK_FLAG := NULL;
  END IF;
END;

DECLARE
  v_can_place VARCHAR2(1);
BEGIN
  BEGIN
    SELECT customer_name INTO :BK_ORDER.CUSTOMER_NAME
      FROM lom_customers
     WHERE customer_id = :BK_ORDER.CUSTOMER_ID;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      om_shared.show_message('Customer ' || :BK_ORDER.CUSTOMER_ID || ' not found.');
      RAISE FORM_TRIGGER_FAILURE;
  END;

  v_can_place := lom_customer_api.can_place_order(:BK_ORDER.CUSTOMER_ID);
  IF v_can_place = 'N' THEN
    om_shared.show_message('Customer ' || :BK_ORDER.CUSTOMER_ID
      || ' is not ACTIVE and cannot place new orders.');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;
END;

BEGIN
  IF :BK_CUSTOMER.CREDIT_LIMIT < 0 THEN
    om_shared.show_message('Credit limit cannot be negative.');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;
END;

BEGIN
  lom_order_api.recalc_order_totals(:BK_ORDER.ORDER_ID);
END;

BEGIN
  IF :BK_INVENTORY.P_ADJUST_QTY IS NULL OR :BK_INVENTORY.P_ADJUST_QTY = 0 THEN
    om_shared.show_message('Enter a non-zero adjustment quantity first.');
    RETURN;
  END IF;

  lom_inventory_api.adjust_quantity(
    p_product_id     => :BK_INVENTORY.PRODUCT_ID,
    p_warehouse_code => :BK_INVENTORY.WAREHOUSE_CODE,
    p_delta          => :BK_INVENTORY.P_ADJUST_QTY,
    p_changed_by     => :GLOBAL.G_USER
  );
  COMMIT;
  :BK_INVENTORY.P_ADJUST_QTY := NULL;
  om_shared.show_message('Inventory adjusted.');
  EXECUTE_QUERY;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    om_shared.show_message('Adjustment failed: ' || SQLERRM);
END;

BEGIN
  -- See 's sibling note on BT_APPROVE above.
  SHOW_ALERT('AL_CONFIRM_REJECT');
  IF :SYSTEM.ALERT_BUTTON = ALERT_BUTTON1 THEN
    UPDATE lom_approvals
       SET status = 'REJECTED',
           approver = :GLOBAL.G_USER,
           approval_date = SYSDATE,
           comments = :BK_APPROVAL.COMMENTS
     WHERE approval_id = :BK_APPROVAL.APPROVAL_ID;

    UPDATE lom_orders
       SET status = 'REJECTED'
     WHERE order_id = :BK_APPROVAL.ORDER_ID;

    COMMIT;
    om_shared.show_message('Order rejected.');
    EXECUTE_QUERY;
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    om_shared.show_message('Rejection failed: ' || SQLERRM);
END;

DECLARE
  v_available NUMBER;
BEGIN
  SELECT NVL(quantity_available, 0) INTO v_available
    FROM lom_inventory
   WHERE product_id = :BK_ORDER_LINE.PRODUCT_ID
     AND warehouse_code = :BK_ORDER.WAREHOUSE_CODE;

  IF :BK_ORDER_LINE.QUANTITY > v_available THEN
    om_shared.show_message('Only ' || v_available || ' unit(s) available for product '
      || :BK_ORDER_LINE.PRODUCT_ID || ' in warehouse ' || :BK_ORDER.WAREHOUSE_CODE);
    RAISE FORM_TRIGGER_FAILURE;
  END IF;

  :BK_ORDER_LINE.LINE_TOTAL := ROUND(
    (:BK_ORDER_LINE.QUANTITY * :BK_ORDER_LINE.UNIT_PRICE) - NVL(:BK_ORDER_LINE.DISCOUNT_AMOUNT, 0), 2);
END;

BEGIN
  :GLOBAL.G_USER := NVL(:GLOBAL.G_USER, GET_APPLICATION_PROPERTY(USERNAME));
  GO_BLOCK('BK_INVENTORY');
  EXECUTE_QUERY;
END;

BEGIN
  SELECT product_name, unit_price
    INTO :BK_ORDER_LINE.PRODUCT_NAME, :BK_ORDER_LINE.UNIT_PRICE
    FROM lom_products
   WHERE product_id = :BK_ORDER_LINE.PRODUCT_ID
     AND active_flag = 'Y';
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    om_shared.show_message('Product ' || :BK_ORDER_LINE.PRODUCT_ID || ' not found or inactive.');
    RAISE FORM_TRIGGER_FAILURE;
END;

DECLARE
  v_default_limit lom_customer_types.default_credit_limit%TYPE;
BEGIN
  SELECT default_credit_limit INTO v_default_limit
    FROM lom_customer_types
   WHERE customer_type_code = :BK_CUSTOMER.CUSTOMER_TYPE_CODE;

  IF :BK_CUSTOMER.CREDIT_LIMIT IS NULL THEN
    COPY(TO_CHAR(v_default_limit), 'BK_CUSTOMER.CREDIT_LIMIT');
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
END;

BEGIN
  :GLOBAL.G_USER := NVL(:GLOBAL.G_USER, GET_APPLICATION_PROPERTY(USERNAME));
  IF :PARAMETER.P_ORDER_ID IS NOT NULL THEN
    SET_BLOCK_PROPERTY('BK_ORDER', DEFAULT_WHERE, 'ORDER_ID = ' || :PARAMETER.P_ORDER_ID);
    GO_BLOCK('BK_ORDER');
    EXECUTE_QUERY;
  ELSE
    GO_BLOCK('BK_ORDER');
  END IF;
END;

BEGIN
  lom_order_api.recalc_order_totals(:BK_ORDER.ORDER_ID);
END;

BEGIN
  -- Baseline for the POST-UPDATE audit trigger below: Forms has no
  -- built-in "old value" accessor, so the pre-change STATUS is stashed
  :GLOBAL.G_OLD_STATUS := :BK_CUSTOMER.STATUS;
END;

BEGIN
  SET_ITEM_PROPERTY('BK_ORDER.STATUS', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.SUBTOTAL', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.TAX_AMOUNT', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.TOTAL_AMOUNT', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.APPROVAL_REQUIRED', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.CREATED_BY', ENABLED, PROPERTY_FALSE);
  SET_ITEM_PROPERTY('BK_ORDER.CREATED_DATE', ENABLED, PROPERTY_FALSE);
END;

BEGIN
  -- ) and LOM_AUDIT_API.log_event. A mechanical translation of
  SHOW_ALERT('AL_CONFIRM_APPROVE');
  IF :SYSTEM.ALERT_BUTTON = ALERT_BUTTON1 THEN
    UPDATE lom_approvals
       SET status = 'APPROVED',
           approver = :GLOBAL.G_USER,
           approval_date = SYSDATE
     WHERE approval_id = :BK_APPROVAL.APPROVAL_ID;

    UPDATE lom_orders
       SET status = 'APPROVED'
     WHERE order_id = :BK_APPROVAL.ORDER_ID;

    COMMIT;
    om_shared.show_message('Order approved.');
    EXECUTE_QUERY;
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    om_shared.show_message('Approval failed: ' || SQLERRM);
END;

DECLARE
  v_paramlist PARAMLIST;
BEGIN
  IF :BK_ORDER.STATUS NOT IN ('PENDING_APPROVAL', 'APPROVED', 'REJECTED') THEN
    om_shared.show_message('This order has no approval history yet.');
    RETURN;
  END IF;

  v_paramlist := GET_PARAMETER_LIST('lom_nav_params');
  IF NOT Id_Null(v_paramlist) THEN
    DESTROY_PARAMETER_LIST(v_paramlist);
  END IF;
  v_paramlist := CREATE_PARAMETER_LIST('lom_nav_params');
  ADD_PARAMETER(v_paramlist, 'P_ORDER_ID', TEXT_PARAMETER, TO_CHAR(:BK_ORDER.ORDER_ID));

  CALL_FORM('APPROVALS', HIDE, NO_REPLACE, QUERY_ONLY, v_paramlist);
END;

BEGIN
  IF :BK_CUSTOMER.CUSTOMER_ID IS NULL THEN
    :BK_CUSTOMER.CUSTOMER_ID := lom_customer_id_seq.NEXTVAL;
  END IF;
  :BK_CUSTOMER.CREATED_BY := :GLOBAL.G_USER;
  :BK_CUSTOMER.CREATED_DATE := SYSDATE;
END;

BEGIN
  lom_order_api.recalc_order_totals(:BK_ORDER.ORDER_ID);
END;

BEGIN
  :GLOBAL.G_USER := NVL(:GLOBAL.G_USER, GET_APPLICATION_PROPERTY(USERNAME));
  IF :PARAMETER.P_CUSTOMER_ID IS NOT NULL THEN
    SET_BLOCK_PROPERTY('BK_CUSTOMER', DEFAULT_WHERE,
      'CUSTOMER_ID = ' || :PARAMETER.P_CUSTOMER_ID);
  END IF;
  GO_BLOCK('BK_CUSTOMER');
  EXECUTE_QUERY;
END;

BEGIN
  EXECUTE_QUERY;
END;

BEGIN
  GO_BLOCK('BK_ORDER');
  ENTER_QUERY;
END;

BEGIN
  IF :BK_ORDER.ORDER_ID IS NULL THEN
    :BK_ORDER.ORDER_ID := lom_order_id_seq.NEXTVAL;
  END IF;
  :BK_ORDER.STATUS := 'DRAFT';
  :BK_ORDER.WAREHOUSE_CODE := NVL(:BK_ORDER.WAREHOUSE_CODE, lom_inventory_api.default_warehouse);
  :BK_ORDER.CREATED_BY := :GLOBAL.G_USER;
  :BK_ORDER.CREATED_DATE := SYSDATE;
END;

DECLARE
  v_paramlist PARAMLIST;
BEGIN
  IF :BK_ORDER_LINE.PRODUCT_ID IS NULL THEN
    om_shared.show_message('Select a product line first.');
    RETURN;
  END IF;

  v_paramlist := GET_PARAMETER_LIST('lom_nav_params');
  IF NOT Id_Null(v_paramlist) THEN
    DESTROY_PARAMETER_LIST(v_paramlist);
  END IF;
  v_paramlist := CREATE_PARAMETER_LIST('lom_nav_params');
  ADD_PARAMETER(v_paramlist, 'P_PRODUCT_ID', TEXT_PARAMETER, TO_CHAR(:BK_ORDER_LINE.PRODUCT_ID));
  ADD_PARAMETER(v_paramlist, 'P_WAREHOUSE_CODE', TEXT_PARAMETER, :BK_ORDER.WAREHOUSE_CODE);

  OPEN_FORM('INVENTORY', ACTIVATE, NO_QUERY_ONLY, v_paramlist);
END;

BEGIN
  IF :BK_ORDER_LINE.DISCOUNT_AMOUNT < 0 THEN
    om_shared.show_message('Discount cannot be negative.');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;

  :BK_ORDER_LINE.LINE_TOTAL := ROUND(
    (:BK_ORDER_LINE.QUANTITY * :BK_ORDER_LINE.UNIT_PRICE) - NVL(:BK_ORDER_LINE.DISCOUNT_AMOUNT, 0), 2);
END;

BEGIN
  IF :BK_ORDER_LINE.LINE_NUMBER IS NULL THEN
    SELECT NVL(MAX(line_number), 0) + 1 INTO :BK_ORDER_LINE.LINE_NUMBER
      FROM lom_order_lines
     WHERE order_id = :BK_ORDER.ORDER_ID;
  END IF;
END;

DECLARE
  v_paramlist PARAMLIST;
BEGIN
  v_paramlist := GET_PARAMETER_LIST('lom_nav_params');
  IF NOT Id_Null(v_paramlist) THEN
    DESTROY_PARAMETER_LIST(v_paramlist);
  END IF;
  v_paramlist := CREATE_PARAMETER_LIST('lom_nav_params');
  ADD_PARAMETER(v_paramlist, 'P_CUSTOMER_ID', TEXT_PARAMETER, TO_CHAR(:BK_ORDER.CUSTOMER_ID));

  CALL_FORM('CUSTOMERS', HIDE, NO_REPLACE, QUERY_ONLY, v_paramlist);
END;

BEGIN
  IF :PARAMETER.P_ORDER_ID IS NOT NULL THEN
    SET_BLOCK_PROPERTY('BK_APPROVAL', DEFAULT_WHERE,
      'ORDER_ID = ' || :PARAMETER.P_ORDER_ID);
  ELSE
    SET_BLOCK_PROPERTY('BK_APPROVAL', DEFAULT_WHERE, 'STATUS = ''PENDING''');
  END IF;
END;

BEGIN
  IF :BK_CUSTOMER.STATUS != :GLOBAL.G_OLD_STATUS THEN
    lom_audit_api.log_event(
      p_entity_name => 'CUSTOMER',
      p_entity_id   => TO_CHAR(:BK_CUSTOMER.CUSTOMER_ID),
      p_action      => 'STATUS_CHANGE',
      p_old_value   => :GLOBAL.G_OLD_STATUS,
      p_new_value   => :BK_CUSTOMER.STATUS,
      p_changed_by  => :GLOBAL.G_USER
    );
  END IF;
  :GLOBAL.G_OLD_STATUS := :BK_CUSTOMER.STATUS;
END;

BEGIN
  IF :PARAMETER.P_WAREHOUSE_CODE IS NOT NULL THEN
    SET_BLOCK_PROPERTY('BK_INVENTORY', DEFAULT_WHERE,
      'WAREHOUSE_CODE = ''' || :PARAMETER.P_WAREHOUSE_CODE || '''');
  ELSE
    SET_BLOCK_PROPERTY('BK_INVENTORY', DEFAULT_WHERE,
      'WAREHOUSE_CODE = ''' || lom_inventory_api.default_warehouse || '''');
  END IF;
  IF :PARAMETER.P_PRODUCT_ID IS NOT NULL THEN
    SET_BLOCK_PROPERTY('BK_INVENTORY', DEFAULT_WHERE,
      GET_BLOCK_PROPERTY('BK_INVENTORY', DEFAULT_WHERE)
      || ' AND PRODUCT_ID = ' || :PARAMETER.P_PRODUCT_ID);
  END IF;
END;

DECLARE
  v_open_orders NUMBER;
BEGIN
  IF :BK_CUSTOMER.STATUS = 'INACTIVE' AND :GLOBAL.G_OLD_STATUS = 'ACTIVE' THEN
    SELECT COUNT(*) INTO v_open_orders
      FROM lom_orders
     WHERE customer_id = :BK_CUSTOMER.CUSTOMER_ID
       AND status NOT IN ('SHIPPED', 'REJECTED', 'CANCELLED');

    IF v_open_orders > 0 THEN
      om_shared.show_message('Cannot inactivate customer ' || :BK_CUSTOMER.CUSTOMER_ID
        || ': ' || v_open_orders || ' open order(s) still in progress.');
      RAISE FORM_TRIGGER_FAILURE;
    END IF;
  END IF;
END;
